using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace TestProject
{
    [TestClass]
    public class InventoryServiceTests
    {
        // DataRow with implicit type conversions:
        // 1L (long) passed to int parameter, 2.0 (double) passed to float parameter
        [TestMethod]
        [DataRow(1L, 2.0, "Widget")]
        [DataRow(3L, 4.0, "Gadget")]
        public void AddItem_ShouldSucceed(int id, float price, string name)
        {
            Assert.IsTrue(id > 0);
            Assert.IsTrue(price > 0);
            Assert.IsFalse(string.IsNullOrEmpty(name));
        }

        // Assert.AreEqual on mixed types (string vs int) -- no common inferred type
        [TestMethod]
        public void VerifyReferenceCode()
        {
            string referenceCode = "ABC";
            int numericId = 123;
            Assert.AreEqual(referenceCode, numericId.ToString());
            // This one uses object,object overload with truly mixed types:
            Assert.AreEqual((object)referenceCode, (object)numericId);
        }

        [TestMethod]
        public void CheckStockLevel()
        {
            object expected = 42;
            object actual = 42;
            Assert.AreEqual(expected, actual);
        }

        [TestMethod]
        [Timeout(5000)]
        public void TimedOperation()
        {
            System.Threading.Thread.Sleep(100);
            Assert.IsTrue(true);
        }
    }
}

